import{_ as r,C as i,c as u,o as c,a3 as s,G as n,j as e,a}from"./chunks/framework.Dokpd4od.js";const _=JSON.parse('{"title":"Two-step manufacturing","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/manufacturing/basic-setup/two-step-manufacturing.md","filePath":"master/supply-chain/manufacturing/basic-setup/two-step-manufacturing.md","lastUpdated":1791902625000}'),l={name:"master/supply-chain/manufacturing/basic-setup/two-step-manufacturing.md"};function p(g,t,h,d,m,f){const o=i("ImagePopup");return c(),u("div",null,[t[0]||(t[0]=s('<h1 id="two-step-manufacturing" tabindex="-1">Two-step manufacturing <a class="header-anchor" href="#two-step-manufacturing" aria-label="Permalink to &quot;Two-step manufacturing&quot;">​</a></h1><p>Two-step manufacturing adds a pick step before production. A storekeeper first moves the components from stock to a staging area. Production then starts from that area. You get a clear record of what left the shelves and when.</p><blockquote><p><strong>In simple words:</strong> Pick the parts first, then build. The pick is its own document.</p></blockquote><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>The <strong>Manufacturing</strong> radio needs <strong>Multi Steps Routes</strong> and <strong>Locations</strong> on in <code>Inventory → Settings → Manage Warehouses</code>. See <a href="./one-step-manufacturing.html">One-step manufacturing</a> for the full gate.</p><h2 id="choose-two-steps" tabindex="-1">Choose two steps <a class="header-anchor" href="#choose-two-steps" aria-label="Permalink to &quot;Choose two steps&quot;">​</a></h2><ol><li>Open <code>Inventory → Configurations → Warehouse Management → Warehouses</code>.</li><li>Click your warehouse, then the <strong>Edit</strong> tab.</li><li>In <strong>Resupply Management</strong>, select <strong>Pick components then manufacture (2 steps)</strong> in the <strong>Manufacturing</strong> radio.</li><li>Click <strong>Save changes</strong>.</li></ol>',7)),n(o,{src:"/images1/manufacturing/step2_warehouse_radio.png",alt:"Warehouse Edit form, Resupply Management, Manufacturing radio with 'Pick components then manufacture (2 steps)' selected, not yet saved"}),t[1]||(t[1]=s(`<div class="info custom-block"><p class="custom-block-title">INFO</p><p>The warehouse now has the location <strong>Pre-Production</strong> and the operation type <strong>Pick Components</strong> (prefix <strong>PC</strong>). See <a href="./../../inventories/warehouses/locations.html">Locations</a> and <a href="./../../inventories/warehouses/operation-types.html">Operation types</a>.</p></div><h2 id="how-the-stock-moves" tabindex="-1">How the stock moves <a class="header-anchor" href="#how-the-stock-moves" aria-label="Permalink to &quot;How the stock moves&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Stock ──► Pre-Production ──► Production ──► Stock</span></span>
<span class="line"><span>  pick transfer (WH/PC)   manufacture    finished product</span></span></code></pre></div><p>The pick transfer moves components from <strong>Stock</strong> to <strong>Pre-Production</strong>. The manufacturing order then consumes them from <strong>Pre-Production</strong>. The finished product goes straight to <strong>Stock</strong>.</p><h2 id="walk-through-a-manufacturing-order" tabindex="-1">Walk through a manufacturing order <a class="header-anchor" href="#walk-through-a-manufacturing-order" aria-label="Permalink to &quot;Walk through a manufacturing order&quot;">​</a></h2><p>This is the same order as in <a href="./one-step-manufacturing.html">One-step manufacturing</a>: <strong>MO/2</strong>, <strong>Business Laptop</strong>, 2 units.</p><ol><li>Open <code>Manufacturing → Operations → Manufacturing Orders</code> and create the order.</li><li>Click <strong>Confirm</strong>. The state becomes <strong>Confirmed</strong>.</li><li>Open the <strong>Transfers</strong> sub page. A transfer such as <strong>WH/PC/16</strong> appears with the state <strong>Ready</strong>.</li></ol>`,7)),n(o,{src:"/images1/manufacturing/step2_transfers.png",alt:"MO/2 Transfers sub page listing WH/PC/16, Source Document MO/2, State Ready"}),t[2]||(t[2]=e("ol",{start:"4"},[e("li",null,[a("Open the transfer and click "),e("strong",null,"Validate"),a(". The components move to "),e("strong",null,"Pre-Production"),a(".")])],-1)),n(o,{src:"/images1/manufacturing/step2_pick_validated.png",alt:"The WH/PC transfer after validation, state Done, product lines Motherboard, RAM 16GB, SSD 512GB, Laptop Battery, LCD Screen 14-inch, Laptop Chassis"}),t[3]||(t[3]=e("ol",{start:"5"},[e("li",null,[a("Back on the order, click "),e("strong",null,"Produce All"),a(". The state becomes "),e("strong",null,"Done"),a(".")])],-1)),n(o,{src:"/images1/manufacturing/step2_mo_done.png",alt:"MO/2 in Done state after the pick was validated"}),t[4]||(t[4]=s('<h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Moment</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Confirm</strong></td><td>Creates the pick transfer <strong>WH/PC/…</strong>, state <strong>Ready</strong>.</td></tr><tr><td><strong>Validate</strong> (pick)</td><td>Components move <strong>Stock</strong> to <strong>Pre-Production</strong>.</td></tr><tr><td><strong>Produce All</strong></td><td>Components are consumed from <strong>Pre-Production</strong>. Finished product enters <strong>Stock</strong>.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Validate the pick transfer before you produce. Until then the components are not at the production area.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./one-step-manufacturing.html">One-step manufacturing</a></li><li><a href="./three-step-manufacturing.html">Three-step manufacturing</a></li><li><a href="./../../inventories/routes/two-step-flow.html">Two-step flow in Inventory</a></li><li><a href="./../workflows/">Manufacturing order lifecycle</a></li></ul>',5))])}const P=r(l,[["render",p]]);export{_ as __pageData,P as default};
